const GN=N(GROUP);
const T={
  STR:'Стрелкова Гюзэль Владимировна',
  VOL:'Волхонский Борис Михайлович',
  JAIN:'Джайн Анил Кумар',
  SAF:'Сафронова Александра Львовна',
  BOCH:'Бочковская Анна Викторовна',
  FIL:'Филимонова Алина Левоновна',
  NIK:'Никольская Ксения Дмитриевна',
  SPEK:'Спектор Илья Борисович'
};
