const southSet=new Set([N(T.SAF),N(T.BOCH),N(T.FIL),N(T.NIK),N(T.SPEK)]);
const indianSet=new Set([N(T.STR),N(T.VOL),N(T.JAIN),'акимушкина екатерина олеговна','диденко мария павловна']);

function isLegacyHindi4Group(v){
  const g=N(v);
  return g===GN || g.includes(GN) ||
    g.includes('23б/и417/7') || g.includes('23б/и417/5') ||
    g.includes('22б/ист-416') || g.includes('22б/ист_хинди') ||
    g.includes('22б/ист-416_хинди') ||
    g==='хинди-синхала' || g==='историки хинди' || g==='историки-хинди' ||
    g.includes('4 курс — история — хинди');
}
function dHas(r,x){ return N(r&&r.discipline).includes(N(x)); }
function isCourse4(r){ return r && (S(r.course).trim()===COURSE || isLegacyHindi4Group(r.group)); }
function removeHindiTarget(r){
  if(!isCourse4(r)) return false;
  const t=N(r.teacher), g=N(r.group);
  if(isLegacyHindi4Group(g)){
    if(dHas(r,'история литературы изучаемой страны') && (indianSet.has(t)||!t)) return true;
    if(dHas(r,'основной восточный язык') && (indianSet.has(t)||!t)) return true;
    if((dHas(r,'второй восточный язык')||dHas(r,'ввя')||dHas(r,'сингаль')||dHas(r,'синхала')) && (t===N(T.VOL)||!t)) return true;
    if(dHas(r,'факультатив') && dHas(r,'санскрит') && (t===N(T.VOL)||!t)) return true;
    if(dHas(r,'социально-политическое развитие') && (southSet.has(t)||!t)) return true;
    if(dHas(r,'основные проблемы') && dHas(r,'южной азии') && t===N(T.SAF)) return true;
    if(dHas(r,'индийские княжества') && t===N(T.SAF)) return true;
    if(dHas(r,'спецсеминар по профилю подготовки') && southSet.has(t)) return true;
    if(dHas(r,'нир студентов') && (t===N(T.SAF)||t===N(T.SPEK))) return true;
  }
  // Старые технические строки кафедр часто имеют только «хинди»/старый код в группе.
  if(S(r.course).trim()===COURSE && (g==='хинди'||g.includes('хинди-синхала')||g.includes('ист-416'))){
    if(indianSet.has(t) && (dHas(r,'история литературы')||dHas(r,'основной восточный язык')||dHas(r,'второй восточный язык')||dHas(r,'ввя')||dHas(r,'санскрит'))) return true;
    if(southSet.has(t) && (dHas(r,'социально-политическое развитие')||dHas(r,'основные проблемы')||dHas(r,'индийские княжества')||dHas(r,'спецсеминар')||dHas(r,'нир студентов'))) return true;
  }
  return false;
}
for(let i=DATA.length-1;i>=0;i--){ if(removeHindiTarget(DATA[i])) DATA.splice(i,1); }

function add(o){ DATA.push(Object.assign({group:GROUP,course:COURSE,direction:'История'},o)); }

