add({day:'Пн',time:'10:40',discipline:'Спецсеминар по профилю подготовки',extra:'ТОЛЬКО: Хазов Ф.; Нецветаева В.',teacher:T.BOCH,room_hint:'423',quality:'01.09.2026, правка №13: индивидуальный спецсеминар А.В. Бочковской; не является занятием всей группы. Сохранён финальный перенос Вт 10:40 → Пн 10:40, ауд.423.'});

