add({day:'Вт',time:'16:20',discipline:'Основной восточный язык (по изучаемому языку)',extra:'хинди',teacher:T.JAIN,room_hint:'239',quality:'01.09.2026, правка №13: ОВЯ хинди 4 курса; сохранён актуальный кафедральный слот.'});
add({day:'Пт',time:'13:00',discipline:'Основной восточный язык (по изучаемому языку)',extra:'хинди',teacher:T.STR,room_hint:'239',quality:'01.09.2026, правка №13: по прямой правке кафедры индийской филологии Пт 13:00 ведёт Г.В. Стрелкова; лишние старые ОВЯ других преподавателей для этой группы удалены.'});

