add({day:'Чт',time:'13:00',discipline:'Спецсеминар по профилю подготовки',extra:'ТОЛЬКО: Кудирмекова Арина Ирбисовна; Эбзеев Артур Борисович',teacher:T.SAF,room_hint:'416',quality:'01.09.2026, правка №13: индивидуальный спецсеминар А.Л. Сафроновой; не является занятием всей группы. Чт 13:00, ауд.416 сохранены по кафедральной сетке.'});
add({day:'Чт',time:'14:40',discipline:'Основные проблемы и тенденции исторического развития стран Южной Азии (семинар)',extra:'2 ч/нед.',teacher:T.SAF,room_hint:'416',quality:'01.09.2026, правка №13: подтверждённый кафедральный слот; четверговые занятия кафедры сохранены подряд, ауд.416.'});
add({day:'Чт',time:'16:20',discipline:'Спецкурс «Индийские княжества в XIX–XX вв. и их наследие в современной Индии»',extra:'2 ч/нед.',teacher:T.SAF,room_hint:'416',quality:'01.09.2026, правка №13: подтверждённый кафедральный слот сразу после семинара 14:40; ауд.416.'});
add({day:'уточняется',time:'уточняется',discipline:'НИР студентов',extra:'ТОЛЬКО: Кудирмекова Арина Ирбисовна; Эбзеев Артур Борисович; 2 ч/нед.',teacher:T.SAF,room_hint:'',quality:'01.09.2026, правка №13: нагрузка подтверждена формой 2026/27, но безопасный точный слот без пересечения с подтверждёнными Вт/Чт курсами не подтверждён. Время намеренно не выдумывается.'});

