const socExtra='единый курс; совместное чтение по кафедральному распределению; 12 ч / 6 пар; А.Л. Сафронова + А.В. Бочковская + А.Л. Филимонова; прежний Вт 13:00 отменён из-за английского; новый единый слот и конкретные даты уточняются; в заявке А.Л. Филимоновой указаны 6 пар в ноябре–декабре';
const socQuality='01.09.2026, правка №13: курс НЕ разбивается на три занятия. В студенческом и преподавательском просмотре это одна дисциплина с тремя преподавателями. Вт 13:00 занят английским; временный перенос правки №12 на Пт 16:20 отменён из-за подтверждённого спецсеминара К.Д. Никольской. Новый общий слот оставлен «уточняется», чтобы не нарушить пожелания/занятость кафедры и не создать новую накладку.';
ALL_SOUTH.forEach(t=>add({day:'уточняется',time:'уточняется',discipline:'Социально-политическое развитие Южной Азии',extra:socExtra,teacher:t,teachers:ALL_SOUTH.slice(),joint_readers:ALL_SOUTH.filter(x=>x!==t),room_hint:'',quality:socQuality}));

// Общий курс «Роль религий…»: не меняем его время/группы, только синхронизируем
// отображение преподавателей — студент и каждый преподаватель видят один и тот же состав.
DATA.forEach(r=>{
  if(!r || S(r.course).trim()!==COURSE || !dHas(r,'роль религий в общественно-политической жизни стран востока')) return;
  if(ROLE_TEACHERS.includes(S(r.teacher).trim())){
    r.teachers=ROLE_TEACHERS.slice();
    r.joint_readers=ROLE_TEACHERS.filter(x=>x!==S(r.teacher).trim());
    const base=N(r.extra);
    if(!base.includes('по отдельным неделям')) r.extra=(S(r.extra).trim()?S(r.extra).trim()+'; ':'')+'коллективный курс; лекторы читают по отдельным неделям; в конкретную неделю ведёт один преподаватель';
  }
});

// Точечная защита от ложного протекания чужих групп в карточку 4и_хинди.
// Другие студенческие группы и их данные не меняются.
const prevFull=typeof fullGroupMatches==='function'?fullGroupMatches:null;
if(prevFull){
  fullGroupMatches=function(key){
    const rows=prevFull(key);
    const k=N(key);
    const isHindiKey=(k==='4и_хинди'||k.includes('4 курс — история — хинди')||k.includes('23б/и423-хинди'));
    if(!isHindiKey || !Array.isArray(rows)) return rows;
    return rows.filter(r=>{
      const g=N(r&&r.group);
      const codes=g.match(/23б\/и\d+/g)||[];
      if(codes.length && !g.includes('23б/и423')) return false;
      if((g==='филологи'||g.includes('все филологи')) && !g.includes('истор')) return false;
      return true;
    });
  };
}

const rows=typeof isServiceRow==='function'?DATA.filter(r=>!isServiceRow(r)):DATA.slice();
PUBLIC_DATA.splice(0,PUBLIC_DATA.length,...rows);
try{if(typeof buildGroupItems==='function')buildGroupItems();}catch(e){}
try{if(typeof buildBrowseList==='function')buildBrowseList();}catch(e){}
